insert into public.skill_definitions
  (id, name, description, kind, hidden, conditions, effect, locks, owner_limit, evolves_from, excludes, uses_per_battle, rumor, enabled)
values
  ('iron_endurance', 'Iron Endurance', 'Your VIT is doubled. You can no longer raise STR or AGI.', 'passive', true, '{"all":[{"counter":"damage_blocked","op":">=","value":5000},{"stat":"STR","op":"==","value":0},{"battle":"attacks_made","op":"==","value":0}]}'::jsonb, '{"stat_multiplier":{"VIT":2}}'::jsonb, array['STR', 'AGI']::text[], null, null, array['glass_fury']::text[], null, 'A knight in the old days never swung his sword once. They say the blows just stopped hurting him.', true),
  ('glass_fury', 'Glass Fury', 'All your damage is multiplied by 1.5. You can no longer raise VIT or HP.', 'passive', true, '{"all":[{"stat":"STR","op":">=","value":50},{"stat":"VIT","op":"==","value":0},{"counter":"crits_landed","op":">=","value":20}]}'::jsonb, '{"passive":{"damage_multiplier":1.5}}'::jsonb, array['VIT', 'HP']::text[], null, null, array['iron_endurance']::text[], null, 'Hit hard, hit true, and never wear armor. Some say the reckless get stronger for it.', true),
  ('arcane_devotion', 'Arcane Devotion', 'INT x1.5 and you regain 3 MP every turn. You can no longer raise STR.', 'passive', true, '{"all":[{"stat":"INT","op":">=","value":60},{"stat":"STR","op":"==","value":0},{"counter":"magic_damage_dealt","op":">=","value":3000}]}'::jsonb, '{"stat_multiplier":{"INT":1.5},"passive":{"mp_regen":3}}'::jsonb, array['STR']::text[], null, null, '{}'::text[], null, 'The hermit by the lake never lifted anything heavier than a book.', true),
  ('poison_resistance', 'Poison Resistance', 'Poison deals half damage and sometimes fails to take hold.', 'passive', true, '{"counter":"times_poisoned","op":">=","value":20}'::jsonb, '{"poison_damage_mult":0.5,"status_resist":{"poison":0.3}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'The swamp toads made me sick for a week. After that they barely bothered me.', true),
  ('glutton', 'Glutton', 'After winning a battle you eat what''s left and restore 25% of your max HP.', 'passive', true, '{"counter":"inedible_eaten","op":">=","value":50}'::jsonb, '{"passive":{"heal_on_win_pct":0.25}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'My cousin eats slime jelly. Raw. He''s never been healthier, somehow.', true),
  ('pacifist', 'Pacifist', 'Enemies won''t attack you until you attack them.', 'passive', true, '{"all":[{"battle":"dungeon_cleared","op":"==","value":true},{"battle":"dungeon_direct_damage","op":"==","value":0}]}'::jsonb, '{"passive":{"pacifist":true}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'A wanderer walked out of the Hollow with clean hands. Nobody knows how the queen fell.', true),
  ('ghost_step', 'Ghost Step', 'After a dodge you vanish for a moment, and the next attack can''t find you.', 'passive', true, '{"counter":"dodge_streak_best","op":">=","value":100}'::jsonb, '{"passive":{"dodge_invisibility":1}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'The rabbits here are fast. Faster still is the one who never lets them land a hit.', true),
  ('last_stand', 'Last Stand', 'Below 25% HP your damage is doubled.', 'passive', true, '{"counter":"low_hp_wins","op":">=","value":20}'::jsonb, '{"passive":{"low_hp_damage":{"threshold":0.25,"multiplier":2}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'Some fighters only wake up when they''re one breath from the end.', true),
  ('bare_knuckle', 'Bare Knuckle', 'Unarmed attacks scale with VIT instead of STR.', 'passive', true, '{"counter":"kills_unarmed","op":">=","value":300}'::jsonb, '{"passive":{"unarmed_stat":"VIT"}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'The old brawler said his fists got harder the more he got hit. Then he punched a golem.', true),
  ('swamp_walker', 'Swamp Walker', 'The poison swamp no longer hurts you.', 'passive', true, '{"all":[{"zone":"mirewood_fields"},{"counter":"swamp_turns","op":">=","value":150}]}'::jsonb, '{"passive":{"hazard_immunity":["poison_swamp"]},"status_resist":{"poison":0.2}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'Spend long enough knee-deep in the bog and it starts to treat you like family.', true),
  ('second_wind', 'Second Wind', 'Active. Restore 30% of your max HP. 8 MP.', 'active', true, '{"all":[{"counter":"battles_won","op":">=","value":5},{"battle":"result","op":"==","value":"win"},{"battle":"min_hp_pct","op":"<=","value":0.3}]}'::jsonb, '{"active":{"mp_cost":8,"heal_pct":0.3}}'::jsonb, '{}'::text[], null, null, '{}'::text[], 2, 'Win a fight you should have lost and your body remembers how to keep going.', true),
  ('twin_cut', 'Twin Cut', 'Active. Two quick sword strikes at 80% power each. 6 MP.', 'active', true, '{"counter":"kills_sword","op":">=","value":25}'::jsonb, '{"active":{"mp_cost":6,"multiplier":0.8,"hits":2,"element":"physical"}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'The guard captain says a blade that''s tasted enough monsters learns to strike twice.', true),
  ('shield_bash', 'Shield Bash', 'Active. Slam with your guard, scaling with VIT. May stun. 5 MP.', 'active', true, '{"any":[{"counter":"kills_large_shield","op":">=","value":20},{"counter":"defend_used","op":">=","value":60}]}'::jsonb, '{"active":{"mp_cost":5,"multiplier":1.2,"scale_stat":"VIT","element":"physical","status":{"type":"stun","chance":0.3,"turns":1}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'A shield is a wall. A wall, swung hard enough, is a hammer.', true),
  ('venom_fang', 'Venom Fang', 'Active. A dagger strike with a high crit chance that often poisons. 6 MP.', 'active', true, '{"counter":"kills_daggers","op":">=","value":25}'::jsonb, '{"active":{"mp_cost":6,"multiplier":1,"crit_bonus":0.2,"element":"physical","status":{"type":"poison","chance":0.6,"turns":3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'Daggers dipped in the swamp long enough start carrying it with them.', true),
  ('piercing_arrow', 'Piercing Arrow', 'Active. An arrow that adds your DEX as damage that ignores defense. 8 MP.', 'active', true, '{"counter":"kills_bow","op":">=","value":25}'::jsonb, '{"active":{"mp_cost":8,"multiplier":0.8,"piercing_stat":"DEX","element":"physical"}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'The hunters say the moss golems can''t be scratched. The good hunters disagree.', true),
  ('fireball', 'Fireball', 'Active. Magic fire that hits the whole area and may burn. 10 MP.', 'active', true, '{"counter":"kills_staff","op":">=","value":25}'::jsonb, '{"active":{"mp_cost":10,"multiplier":1.6,"element":"magic","area":true,"status":{"type":"burn","chance":0.4,"turns":3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'Swing a staff at enough wolves and sparks start coming out of the end.', true),
  ('ground_slam', 'Ground Slam', 'Active. Smash the ground; can''t be dodged and may stun. 9 MP.', 'active', true, '{"counter":"kills_hammer","op":">=","value":25}'::jsonb, '{"active":{"mp_cost":9,"multiplier":1.3,"element":"physical","area":true,"status":{"type":"stun","chance":0.25,"turns":1}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, 'Miss with a hammer often enough and you stop aiming at the enemy. You aim at the ground.', true),
  ('first_light', 'First Light', '+5 to every combat stat. Only one player on the server will ever hold this.', 'passive', true, '{"all":[{"battle":"dungeon_cleared","op":"==","value":true},{"player":"level","op":"<=","value":5}]}'::jsonb, '{"stat_bonus":{"STR":5,"VIT":5,"AGI":5,"DEX":5,"INT":5}}'::jsonb, '{}'::text[], 1, null, '{}'::text[], null, 'The Hollow has waited a long time for someone small and foolish enough to walk out of it.', true),
  ('thorn_retort', 'Thorn Retort', 'Reflects part of the damage you take back at the attacker. Grows with the Thornheart Mantle.', 'passive', false, '{"any":[]}'::jsonb, '{"passive":{"reflect_pct":0.2}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('poison_immunity', 'Poison Immunity', 'Poison no longer affects you.', 'passive', true, '{"all":[{"skill":"poison_resistance"},{"counter":"poisoned_since_death","op":">=","value":100}]}'::jsonb, '{"immunities":["poison"]}'::jsonb, '{}'::text[], null, 'poison_resistance', '{}'::text[], null, 'Resistance is only the start. Keep drinking from the swamp and never fall, and the poison gives up.', true),
  ('venom_body', 'Venom Body', 'Immune to poison, and anything that touches you may be poisoned.', 'passive', true, '{"all":[{"skill":"poison_immunity"},{"battle":"result","op":"==","value":"win"},{"battle":"enemy_is_boss","op":"==","value":true},{"battle":"enemy_type","op":"==","value":"poison"}]}'::jsonb, '{"immunities":["poison"],"passive":{"poison_aura":{"chance":0.5,"turns":3}}}'::jsonb, '{}'::text[], null, 'poison_immunity', '{}'::text[], null, 'Whoever beats the queen of the mire with her own weapon will carry her venom forever.', true)
insert into public.unique_items (id, name, description, stat_bonus, attached_skills)
values
  ('thornheart_mantle', 'Thornheart Mantle', 'Woven from the queen''s own thorns. Only the first to clear the Hollow alone, on their first attempt, can claim it. Grows stronger with its owner.', '{"VIT":10,"INT":5}'::jsonb, array['thorn_retort']::text[])
